def bestAverageFloor(nums, k):
    n = len(nums)
    lo, hi = min(nums), max(nums)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i] - mid
        best_start = 0
        ok = False
        for end in range(k, n + 1):
            if pre[end - k] < best_start:
                best_start = pre[end - k]
            if pre[end] - best_start >= 0:
                ok = True
                break
        if ok:
            lo = mid
        else:
            hi = mid - 1
    return lo
